INSERT INTO devotionals (title, slug, excerpt, content, status, published_at) VALUES
('Uma Só Coisa é Necessária', 'uma-so-coisa-e-necessaria', 'Ela não estava errada, mas estava perigosamente distante, e esse é o tipo de condição espiritual mais sutil e mais perigosa, porque a pessoa continua fazendo...', '<p>"Marta, Marta, estás ansiosa e afadigada com muitas coisas, mas uma só é necessária."<br>Lucas 10:41-42</p>
